class Solution {
    public boolean asteroidsDestroyed(int mass, int[] asteroids) {
        java.util.Arrays.sort(asteroids);
        long current = mass;
        for (int asteroid : asteroids) {
            if (current < asteroid) {
                return false;
            }
            current += asteroid;
        }
        return true;
    }
}

class Solution {
    public boolean asteroidsDestroyed(int mass, int[] asteroids) {
        java.util.PriorityQueue<Integer> minHeap = new java.util.PriorityQueue<>();
        for (int asteroid : asteroids) {
            minHeap.add(asteroid);
        }

        long current = mass;
        while (!minHeap.isEmpty()) {
            int asteroid = minHeap.poll();
            if (current < asteroid) {
                return false;
            }
            current += asteroid;
        }
        return true;
    }
}

class Solution {
    public boolean asteroidsDestroyed(int mass, int[] asteroids) {
        int[] count = new int[100001];
        int maxMass = 0;
        for (int asteroid : asteroids) {
            count[asteroid]++;
            maxMass = Math.max(maxMass, asteroid);
        }

        long current = mass;
        for (int size = 1; size <= maxMass; size++) {
            int frequency = count[size];
            if (frequency == 0) {
                continue;
            }
            if (current < size) {
                return false;
            }
            current += (long) size * frequency;
        }
        return true;
    }
}

class Solution {
    public boolean asteroidsDestroyed(int mass, int[] asteroids) {
        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
        for (int asteroid : asteroids) {
            counts.merge(asteroid, 1, Integer::sum);
        }

        long current = mass;
        for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int asteroid = entry.getKey();
            int frequency = entry.getValue();
            if (current < asteroid) {
                return false;
            }
            current += (long) asteroid * frequency;
        }
        return true;
    }
}
